function partKey(p: SecretumPart): string {
  return p.part === 0 ? `${PREFIX}.${p.discourse}` : `${PREFIX}.${p.discourse}.${p.part}`;
}

function discourseReference(d: number, pages: string): string {
  return `${d === 0 ? "Before Discourse I" : `Discourse ${NUMERALS[d]}`}; Steele 1920, ${pages}`;
}

function span(parts: SecretumPart[]): string {
  const first = parts[0].pages.replace(/^pp?\. /, "").split("–")[0];
  const last = parts.at(-1)!.pages.replace(/^pp?\. /, "").split("–").at(-1)!;
  return first === last ? `p. ${first}` : `pp. ${first}–${last}`;
}

function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [];
  for (let d = 0; d <= 10; d++) {
    const meta = DISCOURSES[d];
    const parts = SECRETUM_PARTS.filter((p) => p.discourse === d);
    const key = `${PREFIX}.${d}`;
    const whole = parts.length === 1 && parts[0].part === 0 ? parts[0] : null;
    const own = whole ? WHOLE[d] : undefined;
    const themes = [...(meta.themes ?? []), ...(own?.themes ?? [])];
    passages.push({
      key,
      divisionKind: d === 0 ? "section" : "chapter",
      label: meta.label,
      reference: discourseReference(d, span(parts)),
      sourceKey: "steele-secretum",
      summary: meta.summary,
      notes: [meta.notes, own?.notes].filter(Boolean).join(" ") || undefined,
      verificationStatus: "unverified",
      layers: [...(whole ? [ismailAliLayer(whole)] : []), ...cited()],
      witnesses: whole ? WITNESS_A : undefined,
      dates: d === 0 ? DATES : undefined,
      themes: themes.length ? themes.map(([themeKey, note]) => ({ themeKey, note })) : undefined,
      images: imagesFor(SECRETUM_IMAGES, key),
    });
    if (whole) continue;
    for (const part of parts) {
      const pk = partKey(part);
      const id = `${d}.${part.part}`;
      const pm = PARTS[id];
      passages.push({
        key: pk,
        parentKey: key,
        divisionKind: "part",
        label: `${d === 0 ? "Before Discourse I" : `Discourse ${NUMERALS[d]}`}, ${part.part}: ${part.label}`,
        reference: `Steele 1920, ${part.pages}`,
        sourceKey: "steele-secretum",
        summary: pm.summary,
        notes: pm.notes,
        verificationStatus: "unverified",
        layers: [ismailAliLayer(part), ...(id === "10.7" ? [LATIN_TABLET] : [])],
        witnesses: WITNESS_OVERRIDE[id] ?? WITNESS_A,
        themes: pm.themes?.map(([themeKey, note]) => ({ themeKey, note })),
        images: imagesFor(SECRETUM_IMAGES, pk),
      });
    }
  }
  return passages;
}

